/**
 * 依頼の対象
 * 依頼が指すもの。描画ノードの ID は保存しない。
 * @see model/target.dt:21
 */
export type ModelTarget =
    /**
     * ワークスペース
     * ワークスペース全体。
     */
    | {
          readonly kind: 'Workspace';
          /** ソースの言語 */
          readonly scope?: SourceLanguage;
      }
    /**
     * モデルの要素
     * `.dt` モデルの要素。
     */
    | {
          readonly kind: 'DtElement';
          /** 要素名 */
          readonly element: ElementName;
      }
    /**
     * ストーミングの要素
     * `.dtes` ストーミングの要素（統合キャンバスでイベントを選ぶと、イベントの定義を指す）。
     */
    | {
          readonly kind: 'DtesElement';
          /** ストーミング名 */
          readonly storming: StormingName;
          /** ストーミング内の要素名 */
          readonly local: StormingLocalName;
      }
    /**
     * イベントの出現
     * タイムラインでのイベントの出現。タイムラインのビューからだけ指せる。
     */
    | {
          readonly kind: 'DtesOccurrence';
          /** ストーミング名 */
          readonly storming: StormingName;
          /** タイムライン名 */
          readonly timeline: TimelineName;
          /** ストーミングのイベント名 */
          readonly eventName: StormingEventName;
          /** 出現の道筋 */
          readonly occurrence: OccurrencePath;
      };

/**
 * Whether two ModelTarget values are equal: by `kind` and the fields of the variant (ADR 0016).
 * @see model/target.dt:21
 */
export function equalModelTarget(a: ModelTarget, b: ModelTarget): boolean {
    if (a.kind !== b.kind) return false;
    if (a.kind === 'Workspace') {
        const y = b as Extract<ModelTarget, { readonly kind: 'Workspace' }>;
        return sameOptional(a.scope, y.scope, ($4: string, $5: string) => $4 === $5);
    }
    if (a.kind === 'DtElement') {
        const y = b as Extract<ModelTarget, { readonly kind: 'DtElement' }>;
        return a.element === y.element;
    }
    if (a.kind === 'DtesElement') {
        const y = b as Extract<ModelTarget, { readonly kind: 'DtesElement' }>;
        return a.storming === y.storming && a.local === y.local;
    }
    if (a.kind === 'DtesOccurrence') {
        const y = b as Extract<ModelTarget, { readonly kind: 'DtesOccurrence' }>;
        return a.storming === y.storming && a.timeline === y.timeline && a.eventName === y.eventName && a.occurrence === y.occurrence;
    }
    return true;
}

/**
 * ソースの範囲
 * ソースの範囲（両端を含む）。
 * @invariant ordered (開始が終了より前): startLine < endLine or (startLine == endLine and startColumn <= endColumn)
 * @see model/target.dt:45
 */
